    // DEFAULT_EXTENSIONS from @babel/core: ['.js','.jsx','.es6','.es','.mjs','.cjs']
    let mut exts: Vec<&str> = vec!["js", "jsx", "es6", "es", "mjs", "cjs", "ts", "tsx"];
    exts.sort();
    exts.join(",")
}

pub struct ParsedArgs {
    pub options: HashMap<String, JsonValue>,
    pub positional: Vec<JsonValue>,
}

fn is_option(value: &str) -> bool {
    value.starts_with("--") || (value.starts_with('-')
        && value.len() > 1
        && !value[1..].chars().next().unwrap().is_ascii_digit()
        && value[1..].chars().next().unwrap() != '.')
}

fn prepare_lookup(defs: &[OptionDef]) -> HashMap<String, usize> {
    let mut map = HashMap::new();
    for (i, d) in defs.iter().enumerate() {
        map.insert(format!("--{}", d.spec.full), i);
        if let Some(abbr) = &d.spec.abbr {
            map.insert(format!("-{}", abbr), i);
        }
        if d.spec.flag {
            map.insert(format!("--no-{}", d.spec.full), i);
        }
    }
    map
}

/// Parse args, replicating the JS argsparser exactly (including its quirks).
pub fn parse(defs: &[OptionDef], args: &[String]) -> Result<ParsedArgs, ParseError> {
    let lookup = prepare_lookup(defs);
    let mut options: HashMap<String, JsonValue> = HashMap::new();
    let mut positional: Vec<JsonValue> = Vec::new();

    // Seed defaults and empty lists.
    for d in defs {
        if let Some(def) = &d.spec.default {
            options.insert(d.key.clone(), def.as_json());
        } else if d.spec.list {
            options.insert(d.key.clone(), JsonValue::Array(vec![]));
        }
    }

    let mut missing_keys: Vec<String> = Vec::new();
    let mut missing_value: Vec<String> = Vec::new();

    let mut i = 0;
    while i < args.len() {
        let arg = &args[i];
        if is_option(arg) {
            let mut option_name = arg.clone();
            let mut value: Option<String> = None;
            if let Some(eq) = arg.find('=') {
                option_name = arg[..eq].to_string();
                value = Some(arg[eq + 1..].to_string());
            }

            let opt_idx = if lookup.contains_key(&option_name) {
                Some(lookup[&option_name])
            } else {
                None
            };

            let key: String;
            let is_flag: bool;
            let is_list: bool;
            let mut process_number = false;
            let mut process_parser_config = false;

            if let Some(idx) = opt_idx {
                let d = &defs[idx];
                key = d.key.clone();
                is_flag = d.spec.flag;
                is_list = d.spec.list;
                process_number = d.spec.process_number;
                process_parser_config = d.spec.process_parser_config;

                // callback: throwError(0, callback()) -> immediate exit.
                if let Some(cb) = &d.spec.callback {
                    match cb {
                        CallbackKind::Help => return Err(ParseError::new(0, get_help_text(defs))),
                        CallbackKind::Version => {
                            return Err(ParseError::new(0, version_text(defs)));
                        }
                    }
                }
            } else {
                // Unknown option: replicate the JS quirk that crashes with
                // "Cannot read properties of undefined (reading 'full')" when the
                // unknown option has no value AND the next arg is also an option
                // (so flag=true). The crash happens later during missingValue
                // iteration because `options[optionName].full` is undefined for
                // the synthesized key. We mirror by recording the raw option
                // name as a missing-value key whose `.full` is unknown, then
                // emitting the JS-equivalent message at the end.
                let real_option_name = option_name
                    .trim_start_matches('-')
                    .trim_start_matches("no-")
                    .to_string();
                let has_prev = options.contains_key(&real_option_name);
                let prev_not_true = match options.get(&real_option_name) {
                    Some(JsonValue::Bool(b)) => !*b,
                    Some(_) => true,
                    None => false,
                };
                let is_list_unknown = has_prev && prev_not_true;

                let next_is_option = i + 1 < args.len() && is_option(&args[i + 1]);
                let flag = !has_prev && value.is_none() && next_is_option;

                key = real_option_name.clone();
                is_flag = flag;
                is_list = is_list_unknown;

                if is_list_unknown {
                    let cur = options.get(&real_option_name).cloned();
                    if let Some(cur) = cur {
                        match cur {
                            JsonValue::Bool(true) => {
                                options.insert(real_option_name.clone(), JsonValue::Array(vec![]));
                            }
                            JsonValue::Array(_) => {}
                            other => {
                                options.insert(
                                    real_option_name.clone(),
                                    JsonValue::Array(vec![other]),
                                );
                            }
                        }
                    }
                }
            }

            if is_flag {
                let v = if option_name.starts_with("--no-") {
                    JsonValue::Bool(false)
                } else if let Some(val) = value.clone() {
                    JsonValue::Bool(val == "1")
                } else {
                    JsonValue::Bool(true)
                };
                options.insert(key, v);
            } else {
                // consume next value if none provided
                if value.is_none() && i + 1 < args.len() && !is_option(&args[i + 1]) {
                    value = Some(args[i + 1].clone());
                    i += 1;
                }
                if let Some(val) = value {
                    let processed = if process_number {
                        JsonValue::from_raw(&val)
                    } else if process_parser_config {
                        match std::fs::read_to_string(&val) {
                            Ok(contents) => match serde_json::from_str::<serde_json::Value>(&contents) {
                                Ok(v) => json_to_value(v),
                                Err(_) => JsonValue::String(val),
                            },
                            Err(_) => JsonValue::String(val),
                        }
                    } else {
                        JsonValue::from_raw(&val)
                    };
                    if is_list {
                        let arr = options
                            .entry(key.clone())
                            .or_insert_with(|| JsonValue::Array(vec![]));
                        if let JsonValue::Array(a) = arr {
                            a.push(processed);
                        }
                    } else {
                        options.insert(key, processed);
                    }
                } else {
                    // missingValue sentinel. For known options this yields the
                    // proper "Missing value: --X requires a value" message; for
                    // unknown options it triggers the JS "reading 'full'" quirk.
                    options.insert(key.clone(), JsonValue::Null);
                    missing_keys.push(key.clone());
                    missing_value.push(option_name.clone());
                }
            }
        } else {
            // positional: digits -> Number, else string
            if arg.chars().all(|c| c.is_ascii_digit()) && !arg.is_empty() {
                match arg.parse::<i64>() {
                    Ok(n) => positional.push(JsonValue::Int(n)),
                    Err(_) => positional.push(JsonValue::String(arg.clone())),
                }
            } else {
                positional.push(JsonValue::String(arg.clone()));
            }
        }
        i += 1;
    }

    // missingValue resolution loop. The JS iterates parsedOptions in insertion
    // order and, for each value === missingValue, throws. For unknown options
    // the synthesized `option` object has no `full`, so accessing
    // `options[optionName].full` throws "Cannot read properties of undefined
    // (reading 'full')". We reproduce the first-encountered behavior.
    for (k, raw_opt) in missing_keys.iter().zip(missing_value.iter()) {
        if let Some(idx) = lookup.get(k) {
            let d = &defs[*idx];
            return Err(ParseError::new(
                1,
                format!(
                    "Missing value: --{} requires a value\n\n---\n\n{}",
                    d.spec.full,
                    get_help_text(defs)
                ),
            ));
        } else {
            // unknown option with missing value -> JS quirk
            let _ = raw_opt;
            return Err(ParseError::new(
                1,
                "Cannot read properties of undefined (reading 'full')".to_string(),
            ));
        }
    }

    // validateOptions: choices must include the parsed value.
    let mut errors: Vec<String> = Vec::new();
    for d in defs {
        if let (Some(choices), Some(val)) = (&d.spec.choices, options.get(&d.key)) {
            let val_str = match val {
                JsonValue::Int(n) => n.to_string(),
                JsonValue::Number(n) => n.to_string(),
                JsonValue::String(s) => s.clone(),
                JsonValue::Bool(b) => b.to_string(),
                _ => String::new(),
            };
            if !choices.contains(&val_str) {
                errors.push(format!(
                    "Error: --{} must be one of the values {}",
                    d.spec.full,
                    choices.join(",")
                ));
            }
        }
    }
    if !errors.is_empty() {
        return Err(ParseError::new(
            1,
            format!("{}\n\n---\n\n{}", errors.join("\n"), get_help_text(defs)),
        ));
    }

    Ok(ParsedArgs { options, positional })
}

/// Help text, byte-for-byte identical to getHelpText(options) in JS.
pub fn get_help_text(defs: &[OptionDef]) -> String {
    let mut ordered: Vec<&OptionDef> = defs.iter().collect();
    ordered.sort_by_key(|d| d.spec.display_index);

    let mut body = String::new();
    for (n, d) in ordered.iter().enumerate() {
        if n > 0 {
            body.push('\n');
        }
        body.push_str(&format_option(d));
    }

    let mut text = format!(
        "\nUsage: jscodeshift [OPTION]... PATH...\n  or:  jscodeshift [OPTION]... -t TRANSFORM_PATH PATH...\n  or:  jscodeshift [OPTION]... -t URL PATH...\n  or:  jscodeshift [OPTION]... --stdin < file_list.txt\n\nApply transform logic in TRANSFORM_PATH (recursively) to every PATH.\nIf --stdin is set, each line of the standard input is used as a path.\n\nOptions:\n\"...\" behind an option means that it can be supplied multiple times.\nAll options are also passed to the transformer, which means you can supply custom options that are not listed here.\n\n{}\n",
        body
    );
    // trimLeft() in JS strips leading whitespace (only the leading newline
    // produced by the template literal's first char).
    while text.starts_with(' ') || text.starts_with('\t') || text.starts_with('\n') {
        text.remove(0);
    }
    text
}

fn format_option(d: &OptionDef) -> String {
    let mut text = String::from("  ");
    if let Some(abbr) = &d.spec.abbr {
        text.push_str(&format!("-{}, ", abbr));
    } else {
        text.push_str("    ");
    }
    if d.spec.flag {
        text.push_str("--(no-)");
    } else {
        text.push_str("--");
    }
    text.push_str(&d.spec.full);
    if let Some(choices) = &d.spec.choices_help {
        if !choices.is_empty() {
            text.push('=');
            text.push_str(&choices.join("|"));
        }
    } else if let Some(mv) = &d.spec.metavar {
        text.push_str(&format!("={}", mv));
    }
    if d.spec.list {
        text.push_str(" ...");
    }
    if d.spec.default_help.is_some() || d.spec.default.is_some() || d.spec.help.is_some() {
        text.push_str("  ");
        if text.len() < 32 {
            let pad = 32 - text.len();
            for _ in 0..pad {
                text.push(' ');
            }
        }
        let text_length = text.len();
        if let Some(help) = &d.spec.help {
            text.push_str(help);
        }
        if d.spec.default_help.is_some() || d.spec.default.is_some() {
            if d.spec.help.is_some() {
                text.push('\n');
            }
            for _ in 0..text_length {
                text.push(' ');
            }
            let dv = d
                .spec
                .default_help
                .clone()
                .or_else(|| d.spec.default.as_ref().map(default_display));
            text.push_str(&format!("(default: {})", dv.unwrap()));
        }
    }
    text
}

fn default_display(d: &DefaultValue) -> String {
    match d {
        DefaultValue::Bool(b) => b.to_string(),
        DefaultValue::Int(i) => i.to_string(),
        DefaultValue::Str(s) => s.clone(),
        DefaultValue::List(v) => {
            let parts: Vec<String> = v
                .iter()
                .map(|j| match j {
                    JsonValue::String(s) => s.clone(),
                    JsonValue::Bool(b) => b.to_string(),
                    JsonValue::Int(i) => i.to_string(),
                    JsonValue::Number(n) => n.to_string(),
                    _ => j.to_json().to_string(),
                })
                .collect();
            parts.join(",")
        }
    }
}

