/// Walk up from a package's resolved entry to find its package.json, mirroring
/// utils/requirePackage.js.
fn package_version(name: &str) -> Option<String> {
    let candidates = resolve_candidates(name)?;
    for dir in candidates {
        let pkg_path = std::path::Path::new(&dir).join("package.json");
        if let Ok(contents) = std::fs::read_to_string(&pkg_path) {
            if let Ok(v) = serde_json::from_str::<serde_json::Value>(&contents) {
                if v.get("name").and_then(|n| n.as_str()) == Some(name) {
                    return v.get("version").and_then(|s| s.as_str()).map(String::from);
                }
            }
        }
    }
    None
}

/// Locate candidate directories containing package.json for `name` by scanning
/// node_modules upwards from the workspace root.
fn resolve_candidates(name: &str) -> Option<Vec<String>> {
    let mut dirs = Vec::new();
    let mut base = std::env::current_dir().ok()?;
    loop {
        let nm = base.join("node_modules").join(name);
        if nm.is_dir() {
            dirs.push(nm.to_string_lossy().into_owned());
            // scoped packages can be nested; also check parent for self-referencing
        }
        if !base.pop() {
            break;
        }
    }
    if dirs.is_empty() { None } else { Some(dirs) }
