            Some(JsonValue::String(s)) => Some(s.clone()),
            _ => None,
        };
        let get_bool = |k: &str| matches!(raw.get(k), Some(JsonValue::Bool(true)));
        let get_i64 = |k: &str| match raw.get(k) {
            Some(JsonValue::Int(n)) => Some(*n),
