            Some(JsonValue::Array(a)) => a
                .iter()
                .filter_map(|v| match v {
                    JsonValue::String(s) => Some(s.clone()),
                    _ => None,
                })
                .collect(),
            _ => vec![],
        };
        Options {
            raw,
            transform,
            cpus: get_i64("cpus"),
            verbose: get_i64("verbose").unwrap_or(0),
            dry: get_bool("dry"),
            print: get_bool("print"),
            babel: get_bool("babel") || matches!(raw.get("babel"), None),
            extensions: get_str("extensions"),
            ignore_pattern: get_str_list("ignorePattern"),
