/// True when stdout is a TTY. picocolors disables colors otherwise; we mirror
/// that so piped output (the common harness case) is plain text.
fn colors_enabled() -> bool {
    use std::os::fd::AsRawFd;
    let fd = std::io::stdout().as_raw_fd();
    unsafe { libc_isatty(fd) }
}

extern "C" {
