fn line_break(s: &str) -> String {
    if s.ends_with('\n') { s.to_string() } else { format!("{}\n", s) }
}

/// Buffered, backpressure-aware stdout writer. The JS Runner uses
/// `process.stdout.write`'s return value to gate buffering; for our purposes a
/// plain lock-protected writer with a drain-buffer is sufficient and preserves
/// ordering.
fn stdout() -> &'static Mutex<Box<dyn Write + Send>> {
    use std::io::stdout;
    static OUT: std::sync::OnceLock<Mutex<Box<dyn Write + Send>>> = std::sync::OnceLock::new();
    OUT.get_or_init(|| {
        let inner: Box<dyn Write + Send> = Box::new(stdout());
        Mutex::new(inner)
    })
}

fn write_out(msg: &str) {
    let mut out = stdout().lock().unwrap();
    let _ = out.write_all(msg.as_bytes());
    let _ = out.flush();
}

fn write_err(msg: &str) {
    let mut e = std::io::stderr().lock();
    let _ = e.write_all(msg.as_bytes());
}

fn log_ok(msg: &str, verbose: i64) {
    if verbose >= 2 {
        write_out(&format!("{}{}", pc_bg_green(&pc_white(" OKK ")), msg));
    }
}
fn log_nochange(msg: &str, verbose: i64) {
    if verbose >= 1 {
        write_out(&format!("{}{}", pc_bg_yellow(&pc_white(" NOC ")), msg));
    }
}
fn log_skip(msg: &str, verbose: i64) {
    if verbose >= 1 {
        write_out(&format!("{}{}", pc_bg_yellow(&pc_white(" SKIP ")), msg));
    }
}
fn log_error(msg: &str, verbose: i64) {
    if verbose >= 0 {
        write_out(&format!("{}{}", pc_bg_red(&pc_white(" ERR ")), msg));
    }
}

fn report(file: &str, msg: &str) {
    write_out(&line_break(&format!("{}{} {}", pc_bg_blue(&pc_white(" REP ")), file, msg)));
}

fn show_file_stats(fs: &FileStats) {
    write_out(&format!(
        "Results: \n{}{}{}{}",
        pc_red(&format!("{} errors\n", fs.error)),
        pc_yellow(&format!("{} unmodified\n", fs.nochange)),
        pc_yellow(&format!("{} skipped\n", fs.skip)),
        pc_green(&format!("{} ok\n", fs.ok)),
    ));
}

fn show_stats(stats: &HashMap<String, i64>) {
    let mut names: Vec<&String> = stats.keys().collect();
    names.sort();
    if !names.is_empty() {
        write_out(&pc_blue("Stats: \n"));
    }
    for name in names {
        write_out(&format!("{}: {}\n", name, stats[name]));
    }
}

