fn num_cpus() -> usize {
    // Prefer sched_getaffinity on Linux; fall back to std's approximation.
    #[cfg(target_os = "linux")]
    unsafe {
        use std::mem::{zeroed, MaybeUninit};
        let mut set: MaybeUninit<libc_cpu_set> = MaybeUninit::zeroed();
        let r = sched_getaffinity(0, std::mem::size_of::<libc_cpu_set>(), set.as_mut_ptr());
        if r == 0 {
            let set = set.assume_init();
            let mut count = 0usize;
            for i in 0..1024 {
                if set.bits[i / 64] & (1u64 << (i % 64)) != 0 {
                    count += 1;
                }
            }
            if count > 0 {
                return count;
            }
        }
    }
    std::thread::available_parallelism()
        .map(|n| n.get())
        .unwrap_or(1)
}

