/// Collect all files under `paths`, applying extension filter and ignore rules.
/// Replicates getAllFiles + dirFiles, including the "Skipping path" stderr line
/// for non-existent top-level paths and the stdout line for broken symlinks.
fn get_all_files(paths: &[String], extensions: Option<&[String]>, ignores: &IgnoreSet) -> Vec<String> {
    let mut all = Vec::new();
    for file in paths {
        if file.is_empty() {
            // stdin may produce empty lines (e.g. trailing newline); the JS
            // baseline prints "Skipping path  which does not exist." for them.
            write_err("Skipping path  which does not exist. \n");
            continue;
        }
        let meta = match std::fs::symlink_metadata(file) {
            Ok(m) => m,
            Err(_) => {
                write_err(&format!("Skipping path {} which does not exist. \n", file));
                continue;
            }
        };
        if meta.is_dir() {
            let mut acc: Vec<String> = Vec::new();
            dir_files(file, &mut acc, ignores);
            for f in acc {
                if filter_file(&f, extensions) {
                    all.push(f);
                }
            }
        } else if !filter_file(file, extensions) || ignores.should_ignore(file) {
            // ignoring
        } else {
            all.push(file.clone());
        }
    }
    all
}

fn filter_file(name: &str, extensions: Option<&[String]>) -> bool {
    match extensions {
        None => true,
        Some(exts) => {
            let ext = Path::new(name)
                .extension()
                .map(|e| format!(".{}", e.to_string_lossy()))
                .unwrap_or_default();
            exts.iter().any(|e| e == &ext)
        }
    }
}

/// Recursive directory walk mirroring dirFiles. Order matches the JS readdir
/// concurrency (effectively readdir order, depth-first per path). We process
/// entries in readdir order to keep file ordering stable and consistent.
fn dir_files(dir: &str, acc: &mut Vec<String>, ignores: &IgnoreSet) {
    let entries = match std::fs::read_dir(dir) {
        Ok(e) => e,
        Err(_) => return, // dirFiles throws on err; non-existent dirs won't reach here
    };
    let mut names: Vec<String> = Vec::new();
    for entry in entries.flatten() {
        names.push(entry.file_name().to_string_lossy().into_owned());
    }
    for name in names {
        let full = join_path(dir, &name);
        match std::fs::symlink_metadata(&full) {
            Err(_) => {
                // symlink issue
                write_out(&format!("Skipping path \"{}\" which does not exist.\n", full));
            }
            Ok(stats) => {
                if ignores.should_ignore(&full) {
                    // ignore
                } else if stats.is_dir() {
                    dir_files(&format!("{}/", full), acc, ignores);
                } else {
                    acc.push(full);
                }
            }
        }
    }
}

/// path.join but treat `dir` already ending with '/' to keep traversal prefix.
fn join_path(dir: &str, name: &str) -> String {
    let p = Path::new(dir);
    let joined = p.join(name);
    joined.to_string_lossy().into_owned()
}

/// Resolve the transform path. http(s) URLs are passed through; local paths
/// are resolved via `path.resolve` (cwd-relative, producing an absolute path).
fn resolve_transform(transform: &str) -> String {
    if transform.starts_with("http://") || transform.starts_with("https://") {
        return transform.to_string();
    }
    let cwd = std::env::current_dir().unwrap_or_else(|_| PathBuf::from("."));
    let p = Path::new(transform);
    let resolved = if p.is_absolute() {
        p.to_path_buf()
    } else {
        cwd.join(p)
    };
    normalize_path(&resolved.to_string_lossy())
}

/// Minimal absolute path normalization collapsing `.`/`..` segments.
fn normalize_path(p: &str) -> String {
    let mut stack: Vec<&str> = Vec::new();
    let abs = p.starts_with('/');
    for seg in p.split('/') {
        match seg {
            "" | "." => {}
            ".." => {
                if stack.last().map(|s| *s != "..").unwrap_or(false) {
                    stack.pop();
                } else if !abs {
                    stack.push("..");
                }
            }
            s => stack.push(s),
        }
    }
    let joined = stack.join("/");
    if abs { format!("/{}", joined) } else if joined.is_empty() { ".".to_string() } else { joined }
}

pub fn run(transform_file: &str, paths: &[String], options: Options) -> Option<RunResult> {
    let resolved = resolve_transform(transform_file);
    let cpus = match options.cpus {
        Some(c) => std::cmp::min(available_cpus(), c as usize),
        None => available_cpus(),
    };
    let extensions: Option<Vec<String>> = options.extensions.as_ref().map(|s| {
        s.split(',').map(|e| format!(".{}", e)).collect()
    });
    let extensions_ref = extensions.as_deref();

    let mut ignores = IgnoreSet::new();
    // ignoreSet is not exposed as a CLI option in this version; kept for parity.
    ignores.add_from_input(&[]);
    ignores.add_from_input(&options.ignore_pattern);
    ignores.add_from_file(&options.ignore_config);
    if options.gitignore {
        let cwd = std::env::current_dir().unwrap_or_else(|_| PathBuf::from("."));
        let gi = cwd.join(".gitignore");
        ignores.add_from_file(&[gi.to_string_lossy().into_owned()]);
    }

    let start = Instant::now();

    // http(s) transform download. Replicates the Runner branch that fetches the
    // transform source and writes it to a tmp file. Implemented in the bridge
    // to avoid a Rust HTTP dependency; here we just detect and defer.
    if resolved.starts_with("http://") || resolved.starts_with("https://") {
        return run_remote(&resolved, paths, options, extensions_ref, &ignores, cpus, start);
    }

    if !Path::new(&resolved).exists() {
        write_err(&format!(
            "{} Transform file {} does not exist \n",
            pc_bg_red(&pc_white("ERROR")),
            resolved
        ));
        return None;
    }

    run_local(&resolved, paths, options, extensions_ref, &ignores, cpus, start)
}

fn run_local(
    transform_file: &str,
    paths: &[String],
    options: Options,
    extensions: Option<&[String]>,
    ignores: &IgnoreSet,
    cpus: usize,
    start: Instant,
) -> Option<RunResult> {
    let files = get_all_files(paths, extensions, ignores);
    let num_files = files.len();

    if num_files == 0 {
        if !options.silent {
            write_out("No files selected, nothing to do. \n");
        }
        return Some(RunResult {
            error: 0,
            ok: 0,
            nochange: 0,
            skip: 0,
            stats: HashMap::new(),
            time_elapsed: "0.000".to_string(),
        });
    }

    let processes = if options.run_in_band { 1 } else { std::cmp::min(num_files, cpus) };
    let chunk_size = if processes > 1 {
        std::cmp::min((num_files + processes - 1) / processes, CHUNK_SIZE)
    } else {
        num_files
    };

    let mut index: usize = 0;
    let mut next_chunk = || -> Vec<String> {
        let take = std::cmp::min(chunk_size, num_files - index);
        if !options.silent && !options.run_in_band && index < num_files {
            write_out(&format!("Sending {} files to free worker...\n", take));
        }
        let chunk: Vec<String> = files[index..index + take].to_vec();
        index += take;
        chunk
    };

    if !options.silent {
        write_out(&format!("Processing {} files... \n", files.len()));
        if !options.run_in_band {
            write_out(&format!("Spawning {} workers...\n", processes));
        }
        if options.dry {
            write_out(&pc_green("Running in dry mode, no files will be written! \n"));
        }
    }

    let file_stats = std::sync::Arc::new(std::sync::Mutex::new(FileStats::default()));
    let stats_counter = std::sync::Arc::new(std::sync::Mutex::new(HashMap::<String, i64>::new()));
    let verbose = options.verbose;
    let silent = options.silent;

    let args = vec![transform_file.to_string(), if options.babel { "babel".to_string() } else { "no-babel".to_string() }];

    // Spawn workers. Each worker is a node bridge process communicating over
    // stdin/stdout line-delimited JSON. We drive them on a single thread each
    // (the JS model uses child_process IPC + EventEmitter, serially processed).
    let mut handles: Vec<WorkerHandle> = Vec::with_capacity(processes);
    for _ in 0..processes {
        match WorkerHandle::spawn(&args) {
            Ok(h) => handles.push(h),
            Err(e) => {
                // Mirror an uncaught spawn error to stderr.
                write_err(&format!("Failed to spawn worker: {}\n", e));
                return None;
            }
        }
    }

    // Send initial chunk to each worker.
    for h in handles.iter_mut() {
        let chunk = next_chunk();
        let _ = h.send_files(&chunk, &options);
    }

    // Drive workers: read messages until all disconnect.
    let mut alive: Vec<bool> = vec![true; handles.len()];
    let mut any_alive = true;
    while any_alive {
        any_alive = false;
        for (wi, h) in handles.iter_mut().enumerate() {
            if !alive[wi] {
                continue;
            }
            match h.recv() {
                Ok(WorkerMessage::Status { status, msg }) => {
                    handle_status(&file_stats, status, &msg, verbose);
                }
                Ok(WorkerMessage::Update { name, quantity }) => {
                    let mut sc = stats_counter.lock().unwrap();
                    *sc.entry(name).or_insert(0) += quantity;
                }
                Ok(WorkerMessage::Free) => {
                    let chunk = next_chunk();
                    if !chunk.is_empty() {
                        let _ = h.send_files(&chunk, &options);
                    } else {
                        // no more work; tell worker to exit by closing stdin
                        let _ = h.shutdown();
                    }
                }
                Ok(WorkerMessage::Report { file, msg }) => {
                    report(&file, &msg);
                }
                Ok(WorkerMessage::Eof) => {
                    alive[wi] = false;
                }
                Err(e) => {
                    // Worker pipe error: treat as disconnect.
                    let _ = e;
                    alive[wi] = false;
                }
            }
            if alive[wi] {
                any_alive = true;
            }
        }
    }

    // Wait for all worker processes to exit (mirrors disconnect promise).
    for h in handles.iter_mut() {
        let _ = h.wait();
    }

    let elapsed = start.elapsed();
    let time_elapsed = format!("{:.3}", elapsed.as_secs_f64());
    if !silent {
        write_out("All done. \n");
        let fs = file_stats.lock().unwrap();
        show_file_stats(&fs);
        let sc = stats_counter.lock().unwrap();
        show_stats(&sc);
        write_out(&format!("Time elapsed: {}seconds \n", time_elapsed));
        if options.fail_on_error && fs.error > 0 {
            std::process::exit(1);
        }
    }

    let fs = file_stats.lock().unwrap();
    let sc = stats_counter.lock().unwrap();
    Some(RunResult {
        error: fs.error,
        ok: fs.ok,
        nochange: fs.nochange,
        skip: fs.skip,
        stats: sc.clone(),
        time_elapsed,
    })
}

fn handle_status(fs: &std::sync::Arc<std::sync::Mutex<FileStats>>, status: &str, msg: &str, verbose: i64) {
    let mut fs = fs.lock().unwrap();
    let m = line_break(msg);
    match status {
        "ok" => { fs.ok += 1; log_ok(&m, verbose); }
        "nochange" => { fs.nochange += 1; log_nochange(&m, verbose); }
        "skip" => { fs.skip += 1; log_skip(&m, verbose); }
        "error" => { fs.error += 1; log_error(&m, verbose); }
        _ => {}
    }
}

/// Remote (http/https) transform handling. We hand the URL to the bridge, which
/// downloads it via Node's http/https (preserving the exact tmp-file flow) and
/// reports back the local transform path before running. This keeps network
/// behavior identical to the JS Runner without adding a Rust HTTP stack.
fn run_remote(
    url: &str,
    paths: &[String],
    options: Options,
    extensions: Option<&[String]>,
    ignores: &IgnoreSet,
    cpus: usize,
    start: Instant,
) -> Option<RunResult> {
    // Delegate to bridge in two phases: first fetch the transform to a temp
    // file, then run locally. We perform the fetch by invoking the bridge with
    // a "fetch" command.
    match crate::worker::fetch_remote_transform(url) {
        Ok(local) => run_local(&local, paths, options, extensions, ignores, cpus, start),
        Err(e) => {
            write_err(&format!("Error fetching transform: {}\n", e));
            None
        }
    }
}

