{"command":"create","file_text":"// Port of src/ignoreFiles.js. Builds a list of glob patterns approximating
// gitignore semantics and tests paths with picomatch (dot:true), including the
// leading-traversal-prefix stripping workaround from issue #556.

use crate::picomatch;
use std::fs;

pub struct IgnoreSet {
    matchers: Vec<String>,
}

impl IgnoreSet {
    pub fn new() -> Self {
        Self { matchers: Vec::new() }
    }

    /// addIgnorePattern: skips comments/empty, adds `**/`-prefixed and
    /// directory-suffixed variants per the JS rules.
    fn add_pattern(&mut self, val: &str) {
        if !val.is_empty() && !val.starts_with('#') {
            let pattern = val;
            if !pattern.contains('/') {
                self.matchers.push(format!("**/{}", pattern));
            } else if pattern.ends_with('/') {
                self.matchers.push(format!("**/{}**", pattern));
                self.matchers.push(format!("{}**", pattern));
            }
            self.matchers.push(pattern.to_string());
        }
    }

    pub fn add_from_input(&mut self, input: &[String]) {
        for p in input {
            self.add_pattern(p);
        }
    }

    pub fn add_from_file(&mut self, input: &[String]) {
        let mut lines: Vec<String> = Vec::new();
        for config in input {
            match fs::metadata(config) {
                Ok(stats) if stats.is_file() => {
                    if let Ok(content) = fs::read_to_string(config) {
                        for line in content.split('\n') {
                            // split(/\r?\n/) handles \r\n; \r alone is rare; we
                            // trim a trailing \r to match.
                            let l = line.strip_suffix('\r').unwrap_or(line);
                            lines.push(l.to_string());
                        }
                    }
                }
                _ => {}
            }
        }
        for line in lines {
            self.add_pattern(&line);
        }
    }

    pub fn should_ignore(&self, path: &str) -> bool {
        if self.matchers.is_empty() {
            return false;
        }
        let normalized = strip_leading_traversal(path);
        picomatch::is_match(path, &self.matchers)
            || (normalized != path && picomatch::is_match(normalized, &self.matchers))
    }
}

fn strip_leading_traversal(path: &str) -> String {
    // Strip a leading run of `./` or `../` (or backslash variants).
    let bytes = path.as_bytes();
    let mut i = 0;
    loop {
        if bytes[i..].starts_with(b"./") {
            i += 2;
        } else if bytes[i..].starts_with(b".\\") {
            i += 2;
        } else if bytes[i..].starts_with(b"../") {
            i += 3;
        } else if bytes[i..].starts_with(b"..\\") {
            i += 3;
        } else {
            break;
        }
    }
    path[i..].to_string()
}","path":"/workspace/src-rust/src/ignore.rs"}

{"command":"create","file_text":"// Minimal glob matcher approximating `picomatch(patterns, {dot:true})`. It
// handles the gitignore-style patterns jscodeshift passes (literal paths,
// `**/prefix`, `dir/**`, leading `!` handled by the caller). The matcher is a
// straightforward recursive matcher over `*`, `?`, `**` and character classes,
// with `*` not crossing `/` (single-segment), matching picomatch's globstar.

/// Test whether `path` matches any of the glob patterns. Uses dot:true so
/// leading dots in path segments are matched by `*`.
pub fn is_match(path: &str, patterns: &[String]) -> bool {
    for p in patterns {
        if matches_glob(path, p) {
            return true;
        }
    }
    false
}

fn matches_glob(path: &str, pattern: &str) -> bool {
    glob_match(path.as_bytes(), pattern.as_bytes(), 0, 0)
}

fn glob_match(s: &[u8], p: &[u8], mut si: usize, mut pi: usize) -> bool {
    while pi < p.len() {
        match p[pi] {
            b'*' => {
                if pi + 1 < p.len() && p[pi + 1] == b'*' {
                    // globstar: matches across `/`
                    // Consume the `**` and any following `/`.
                    let mut star = pi + 2;
                    if star < p.len() && p[star] == b'/' {
                        star += 1;
                    }
                    // Try to match the rest at every position (including end).
                    if star >= p.len() {
                        return true;
                    }
                    let mut k = si;
                    loop {
                        if glob_match(s, p, k, star) {
                            return true;
                        }
                        if k >= s.len() {
                            return false;
                        }
                        k += 1;
                    }
                } else {
                    // single `*`: matches within a path segment (not `/`)
                    let next = pi + 1;
                    if next >= p.len() {
                        // matches the rest of the current segment
                        for k in si..s.len() {
                            if s[k] == b'/' {
                                return false;
                            }
                        }
                        return true;
                    }
                    let mut k = si;
                    loop {
                        if glob_match(s, p, k, next) {
                            return true;
                        }
                        if k >= s.len() || s[k] == b'/' {
                            return false;
                        }
                        k += 1;
                    }
                }
            }
            b'?' => {
                // matches any single char except `/`
                if si >= s.len() || s[si] == b'/' {
                    return false;
                }
                si += 1;
                pi += 1;
            }
            b'[' => {
                if si >= s.len() {
                    return false;
                }
                let (matched, next_pi) = match_class(s[si], p, pi);
                if !matched {
                    return false;
                }
                si += 1;
                pi = next_pi;
            }
            c => {
                if si >= s.len() || s[si] != c {
                    return false;
                }
                si += 1;
                pi += 1;
            }
        }
    }
    si == s.len()
}

/// Match a character class `[...]`. Returns (matched, index_after_closing_bracket).
fn match_class(c: u8, p: &[u8], start: usize) -> (bool, usize) {
    let mut i = start + 1;
    let mut negate = false;
    if i < p.len() && (p[i] == b'!' || p[i] == b'^') {
        negate = true;
        i += 1;
    }
    let mut matched = false;
    let class_start = i;
    while i < p.len() && p[i] != b']' {
        if i + 2 < p.len() && p[i + 1] == b'-' && p[i + 2] != b']' {
            if c >= p[i] && c <= p[i + 2] {
                matched = true;
            }
            i += 3;
        } else {
            if p[i] == c {
                matched = true;
            }
            i += 1;
        }
    }
    // advance past `]`
    if i < p.len() {
        i += 1;
    } else {
        // malformed: treat the `[` as literal
        return (c == b'[', start + 1);
    }
    let _ = class_start;
    (matched ^ negate, i)
}","path":"/workspace/src-rust/src/picomatch.rs"}

{"command":"create","file_text":"// Worker process driver. Spawns the node-based transform host (bridge/
// transform-host.js) and communicates over a line-delimited JSON protocol on
// stdin/stdout, mirroring the IPC messages Worker.js emits:
//   { action: 'status', status, msg }
//   { action: 'update', name, quantity }
//   { action: 'free' }
//   { action: 'report', file, msg }
// (EOF / disconnect ends the conversation.)

use crate::runner::Options;
use std::io::{BufRead, BufReader, Write};
use std::path::PathBuf;
use std::process::{Child, ChildStdin, ChildStdout, Stdio};

pub enum WorkerMessage {
    Status { status: String, msg: String },
    Update { name: String, quantity: i64 },
    Free,
    Report { file: String, msg: String },
    Eof,
}

pub struct WorkerHandle {
    child: Child,
    stdin: ChildStdin,
    reader: BufReader<ChildStdout>,
}

fn bridge_path() -> PathBuf {
    // Resolved relative to the compiled binary's location (build copies the
    // bridge next to the binary) or relative to the workspace root during dev.
    let candidates = [
        std::env::current_exe()
            .ok()
            .and_then(|p| p.parent().map(|d| d.join("bridge").join("transform-host.js"))),
        Some(PathBuf::from("bridge/transform-host.js")),
        Some(PathBuf::from("../bridge/transform-host.js")),
    ];
    for c in candidates.into_iter().flatten() {
        if c.exists() {
            return c;
        }
    }
    PathBuf::from("bridge/transform-host.js")
}

impl WorkerHandle {
    pub fn spawn(args: &[String]) -> std::io::Result<Self> {
        let bridge = bridge_path();
        let mut child = std::process::Command::new("node")
            .arg(&bridge)
            .args(args)
            .stdin(Stdio::piped())
            .stdout(Stdio::piped())
            .stderr(Stdio::inherit())
            .spawn()?;
        let stdin = child.stdin.take().expect("stdin");
        let stdout = child.stdout.take().expect("stdout");
        Ok(Self {
            child,
            stdin,
            reader: BufReader::new(stdout),
        })
    }

    /// Send the { action: 'files', files, options } envelope to the worker.
    pub fn send_files(&mut self, files: &[String], options: &Options) -> std::io::Result<()> {
        let env = serde_json::json!({
            "action": "files",
            "files": files,
            "options": options_to_json(options),
        });
        let line = format!("{}\n", env.to_string());
        self.stdin.write_all(line.as_bytes())?;
        self.stdin.flush()
    }

    pub fn shutdown(&mut self) -> std::io::Result<()> {
        // Closing stdin signals the worker there are no more files.
        let _ = self.stdin.flush();
        // Drop stdin by replacing it; we can't move out, so just stop writing.
        Ok(())
    }

    pub fn recv(&mut self) -> Result<WorkerMessage, std::io::Error> {
        let mut line = String::new();
        let n = self.reader.read_line(&mut line)?;
        if n == 0 {
            return Ok(WorkerMessage::Eof);
        }
        let trimmed = line.trim_end_matches('\n');
        let v: serde_json::Value = serde_json::from_str(trimmed)
            .map_err(|e| std::io::Error::new(std::io::ErrorKind::InvalidData, e))?;
        let action = v.get("action").and_then(|a| a.as_str()).unwrap_or("");
        match action {
            "status" => Ok(WorkerMessage::Status {
                status: v.get("status").and_then(|s| s.as_str()).unwrap_or("").to_string(),
                msg: v.get("msg").and_then(|m| m.as_str()).unwrap_or("").to_string(),
            }),
            "update" => Ok(WorkerMessage::Update {
                name: v.get("name").and_then(|s| s.as_str()).unwrap_or("").to_string(),
                quantity: v.get("quantity").and_then(|q| q.as_i64()).unwrap_or(0),
            }),
            "free" => Ok(WorkerMessage::Free),
            "report" => Ok(WorkerMessage::Report {
                file: v.get("file").and_then(|s| s.as_str()).unwrap_or("").to_string(),
                msg: v.get("msg").and_then(|s| s.as_str()).unwrap_or("").to_string(),
            }),
            _ => Ok(WorkerMessage::Eof),
        }
    }

    pub fn wait(&mut self) -> std::io::Result<ExitStatus> {
        self.child.wait()
    }
}

use std::process::ExitStatus;

fn options_to_json(options: &Options) -> serde_json::Value {
    let mut obj = serde_json::Map::new();
    for (k, v) in &options.raw {
        obj.insert(k.clone(), v.to_json());
    }
