fn main() {
    let defs = args_parser::build_options();
    let raw_args: Vec<String> = std::env::args().skip(1).collect();

    let parsed = match args_parser::parse(&defs, &raw_args) {
        Ok(p) => p,
        Err(e) => {
            let (stream_err, code) = (e.exit_code != 0, e.exit_code);
            if stream_err {
                eprint!("{}", e.message);
            } else {
                print!("{}", e.message);
            }
            exit(code);
        }
    };

    // Validate positional / stdin requirement (mirrors bin/jscodeshift.js).
    let stdin_flag = matches!(parsed.options.get("stdin"), Some(args_parser::JsonValue::Bool(true)));
    if parsed.positional.is_empty() && !stdin_flag {
        eprint!(
            "Error: You have to provide at least one file/directory to transform.\n\n---\n\n{}",
            args_parser::get_help_text(&defs)
        );
        exit(1);
    }

    let transform = match parsed.options.get("transform") {
        Some(args_parser::JsonValue::String(s)) => s.clone(),
        _ => "./transform.js".to_string(),
    };

    let options = runner::Options::from_raw(parsed.options, transform.clone());

    let paths: Vec<String> = if stdin_flag {
        runner::read_stdin_paths()
    } else {
        parsed
            .positional
            .iter()
            .map(|v| match v {
                args_parser::JsonValue::String(s) => s.clone(),
                args_parser::JsonValue::Int(n) => n.to_string(),
                args_parser::JsonValue::Number(n) => n.to_string(),
                _ => String::new(),
            })
            .collect()
    };

    let result = runner::run(&transform, &paths, options);
    match result {
        Some(r) => {
            if r.error > 0 && should_fail(&r) {
                exit(1);
            }
            exit(0);
        }
        None => exit(1),
    }
}

