{"command":"create","file_text":"#!/usr/bin/env node
/*
 * bridge/transform-host.js
 *
 * Minimal JavaScript compatibility bridge retained to load and execute
 * transforms. It is driven by the Rust CLI over a line-delimited JSON
 * protocol on stdin/stdout and reuses the first-party jscodeshift core
 * (Collection, core, template, parser adapters, builders, comments,
 * formatting) and its installed parser/recast/ast-types dependencies.
 *
 * The public package entrypoint (`index.js`) and the transform-facing API
 * are unchanged; this file only stands in for src/Worker.js so the Rust
 * process can orchestrate transforms without re-implementing the AST layer.
 *
 * Protocol (one JSON message per line):
 *   stdin  -> { action: 'files', files: [string], options: {...} }
 *   stdout <- { action: 'status', status: 'ok'|'nochange'|'skip'|'error', msg }
 *   stdout <- { action: 'update', name: string, quantity: number }
 *   stdout <- { action: 'free' }
 *   stdout <- { action: 'report', file: string, msg: string }
 * Closing stdin signals no-more-work.
 */

'use strict';

const fs = require('graceful-fs');
const writeFileAtomic = require('write-file-atomic');
const { DEFAULT_EXTENSIONS } = require('@babel/core');

const getParser = require('./getParser');
const jscodeshift = require('./core');

let presetEnv;
try {
  presetEnv = require('@babel/preset-env');
} catch (_) {}

let transform = null;
let parserFromTransform = null;

function setup(tr, babel) {
  if (babel === 'babel') {
    const presets = [];
    if (presetEnv) {
      presets.push([presetEnv.default, { targets: { node: true } }]);
    }
    presets.push(
      /\.tsx?$/.test(tr)
        ? require('@babel/preset-typescript').default
        : require('@babel/preset-flow').default
    );

    require('@babel/register')({
      configFile: false,
      babelrc: false,
      presets,
      plugins: [
        require('@babel/plugin-transform-class-properties').default,
        require('@babel/plugin-transform-nullish-coalescing-operator').default,
        require('@babel/plugin-transform-optional-chaining').default,
        require('@babel/plugin-transform-modules-commonjs').default,
        require('@babel/plugin-transform-private-methods').default,
      ],
      extensions: [...DEFAULT_EXTENSIONS, '.ts', '.tsx'],
      ignore: [
        /@babel\/parser/,
        /\/flow-parser\//,
        /\/recast\//,
        /\/ast-types\//,
      ],
    });
  }

  const module = require(tr);
  transform = typeof module.default === 'function' ? module.default : module;
  if (module.parser) {
    parserFromTransform =
      typeof module.parser === 'string' ? getParser(module.parser) : module.parser;
  }
}

function prepareJscodeshift(options) {
  const parser = parserFromTransform || getParser(options.parser, options.parserConfig);
  return jscodeshift.withParser(parser);
}

function notify(data) {
  process.stdout.write(JSON.stringify(data) + '\n');
}

function free() {
  notify({ action: 'free' });
}

function updateStatus(status, file, msg) {
  msg = msg ? file + ' ' + msg : file;
  notify({ action: 'status', status, msg });
}

function report(file, msg) {
  notify({ action: 'report', file, msg });
}

function empty() {}

function stats(name, quantity) {
  quantity = typeof quantity !== 'number' ? 1 : quantity;
  notify({ action: 'update', name, quantity });
}

function trimStackTrace(trace) {
  if (!trace) return '';
  const lines = trace.split('\n');
  const result = [];
  lines.every(function (line) {
    if (line.indexOf(__filename) === -1) {
      result.push(line);
      return true;
    }
  });
  return result.join('\n');
}

function processFile(file, options, done) {
  fs.readFile(file, async function (err, source) {
    if (err) {
      updateStatus('error', file, 'File error: ' + err);
      done();
      return;
    }
    source = source.toString();
    try {
      const j = prepareJscodeshift(options);
      const out = await transform(
        { path: file, source },
        {
          j,
          jscodeshift: j,
          stats: options.dry ? stats : empty,
          report: (msg) => report(file, msg),
        },
        options
      );
      if (!out || out === source) {
        updateStatus(out ? 'nochange' : 'skip', file);
        done();
        return;
      }
      if (options.print) {
        console.log(out);
      }
      if (!options.dry) {
        writeFileAtomic(file, out, function (err) {
          if (err) {
            updateStatus('error', file, 'File writer error: ' + err);
          } else {
            updateStatus('ok', file);
          }
          done();
        });
      } else {
        updateStatus('ok', file);
        done();
      }
    } catch (err) {
      updateStatus(
        'error',
        file,
        'Transformation error (' +
          err.message.replace(/\n/g, ' ') +
          ')\n' +
          trimStackTrace(err.stack)
      );
      done();
    }
  });
}

function run(data) {
  const files = data.files;
  const options = data.options || {};
  if (!files || !files.length) {
    free();
    return;
  }
  let remaining = files.length;
  const checkDone = () => {
    if (--remaining === 0) free();
  };
  files.forEach((file) => processFile(file, options, checkDone));
}

let pending = '';
process.stdin.setEncoding('utf8');
process.stdin.on('data', (chunk) => {
  pending += chunk;
  let nl;
  while ((nl = pending.indexOf('\n')) !== -1) {
    const line = pending.slice(0, nl);
    pending = pending.slice(nl + 1);
    if (!line.trim()) continue;
    let data;
    try {
      data = JSON.parse(line);
    } catch (e) {
      continue;
    }
    run(data);
  }
});
process.stdin.on('end', () => {
  // No more files will be sent; allow in-flight work to complete, then exit.
  // The Rust driver waits for stdout EOF (worker disconnect).
  setTimeout(() => process.exit(0), 0);
});

// Fetch mode: download a remote transform to a tmp file and print the path.
if (process.argv[2] === 'fetch') {
  const url = process.argv[3];
  const tmp = require('tmp');
  tmp.setGracefulCleanup();
  const http = require('http');
  const https = require('https');
  (url.indexOf('https') !== 0 ? http : https).get(url, (res) => {
    let contents = '';
    res
      .on('data', (d) => {
        contents += d.toString();
      })
      .on('end', () => {
        const ext = require('path').extname(url);
        tmp.file({ prefix: 'jscodeshift', postfix: ext }, (err, path, fd) => {
          if (err) {
            process.stderr.write(String(err) + '\n');
            process.exit(1);
          }
          fs.write(fd, contents, (err) => {
            if (err) {
              process.stderr.write(String(err) + '\n');
              process.exit(1);
            }
            fs.close(fd, (err) => {
              if (err) {
                process.stderr.write(String(err) + '\n');
                process.exit(1);
              }
              process.stdout.write(path + '\n');
              process.exit(0);
            });
          });
        });
      });
  }).on('error', (e) => {
    process.stderr.write(String(e) + '\n');
    process.exit(1);
  });
  return;
}

setup(process.argv[2], process.argv[3]);","path":"/workspace/bridge/transform-host.js"}

