impl DefaultValue {
    fn as_json(&self) -> JsonValue {
        match self {
            DefaultValue::Bool(b) => JsonValue::Bool(*b),
            DefaultValue::Int(i) => JsonValue::Number((*i as f64).into()),
            DefaultValue::Str(s) => JsonValue::String(s.clone()),
            DefaultValue::List(v) => JsonValue::Array(v.clone()),
        }
    }
}

/// A JSON-ish value used for option values. Mirrors what the JS parser stores:
/// booleans (flags), numbers, strings, arrays (lists), and arbitrary JSON.
#[derive(Debug, Clone, PartialEq)]
pub enum JsonValue {
    Null,
    Bool(bool),
    Number(f64),
    Int(i64),
    String(String),
    Array(Vec<JsonValue>),
    Object(serde_json::Map<String, JsonValue>),
}

impl JsonValue {
    pub fn to_json(&self) -> serde_json::Value {
        match self {
            JsonValue::Null => serde_json::Value::Null,
            JsonValue::Bool(b) => serde_json::Value::Bool(*b),
            JsonValue::Number(n) => {
                serde_json::Number::from_f64(*n)
                    .map(serde_json::Value::Number)
                    .unwrap_or(serde_json::Value::Null)
            }
            JsonValue::Int(i) => serde_json::Value::Number(serde_json::Number::from(*i)),
            JsonValue::String(s) => serde_json::Value::String(s.clone()),
            JsonValue::Array(a) => {
                serde_json::Value::Array(a.iter().map(|v| v.to_json()).collect())
            }
            JsonValue::Object(o) => {
                let mut m = serde_json::Map::new();
                for (k, v) in o {
                    m.insert(k.clone(), v.to_json());
                }
                serde_json::Value::Object(m)
            }
        }
    }

    /// Try to parse a raw string as JSON (for nomnom compatibility); fall back
    /// to the raw string. Mirrors `option.process` in the JS parser.
    fn from_raw(s: &str) -> JsonValue {
        match serde_json::from_str::<serde_json::Value>(s) {
            Ok(v) => json_to_value(v),
            Err(_) => JsonValue::String(s.to_string()),
        }
    }
}

fn json_to_value(v: serde_json::Value) -> JsonValue {
    match v {
        serde_json::Value::Null => JsonValue::Null,
        serde_json::Value::Bool(b) => JsonValue::Bool(b),
        serde_json::Value::Number(n) => {
            if let Some(i) = n.as_i64() {
                JsonValue::Int(i)
            } else if let Some(f) = n.as_f64() {
                JsonValue::Number(f)
            } else {
                JsonValue::Number(0.0)
            }
        }
        serde_json::Value::String(s) => JsonValue::String(s),
        serde_json::Value::Array(a) => JsonValue::Array(a.into_iter().map(json_to_value).collect()),
        serde_json::Value::Object(o) => {
            let mut m = serde_json::Map::new();
            for (k, val) in o {
                m.insert(k, json_to_value(val));
            }
            JsonValue::Object(m)
        }
    }
}","path":"/workspace/src-rust/src/args_parser.rs"}

{"command":"str_replace","new_str":"pub struct ParsedArgs {
    pub options: HashMap<String, serde_json::Value>,
    pub positional: Vec<serde_json::Value>,
}

fn is_option(value: &str) -> bool {
    // Matches the JS regex /^--?/: true for any value beginning with a dash.
    value.starts_with('-')
}

/// Parse a raw string the way nomnom's `option.process` does: try JSON first,
/// fall back to the raw string.
fn parse_raw(s: &str) -> serde_json::Value {
    match serde_json::from_str::<serde_json::Value>(s) {
        Ok(v) => v,
        Err(_) => serde_json::Value::String(s.to_string()),
    }
}

fn prepare_lookup(defs: &[OptionDef]) -> HashMap<String, usize> {
    let mut map = HashMap::new();
    for (i, d) in defs.iter().enumerate() {
        map.insert(format!("--{}", d.spec.full), i);
        if let Some(abbr) = &d.spec.abbr {
            map.insert(format!("-{}", abbr), i);
        }
        if d.spec.flag {
            map.insert(format!("--no-{}", d.spec.full), i);
        }
    }
    map
}

/// Parse args, replicating the JS argsparser exactly (including its quirks).
pub fn parse(defs: &[OptionDef], args: &[String]) -> Result<ParsedArgs, ParseError> {
    let lookup = prepare_lookup(defs);
    let mut options: HashMap<String, serde_json::Value> = HashMap::new();
    let mut positional: Vec<serde_json::Value> = Vec::new();

    // Seed defaults and empty lists.
    for d in defs {
        if let Some(def) = &d.spec.default {
            options.insert(d.key.clone(), def.as_json());
        } else if d.spec.list {
            options.insert(d.key.clone(), serde_json::Value::Array(vec![]));
        }
    }

    let mut missing_keys: Vec<String> = Vec::new();
    let mut missing_value: Vec<String> = Vec::new();

    let mut i = 0;
    while i < args.len() {
        let arg = &args[i];
        if is_option(arg) {
            let mut option_name = arg.clone();
            let mut value: Option<String> = None;
            if let Some(eq) = arg.find('=') {
                option_name = arg[..eq].to_string();
                value = Some(arg[eq + 1..].to_string());
            }

            let opt_idx = if lookup.contains_key(&option_name) {
                Some(lookup[&option_name])
            } else {
                None
            };

            let key: String;
            let is_flag: bool;
            let is_list: bool;
            let mut process_number = false;
            let mut process_parser_config = false;

            if let Some(idx) = opt_idx {
                let d = &defs[idx];
                key = d.key.clone();
                is_flag = d.spec.flag;
                is_list = d.spec.list;
                process_number = d.spec.process_number;
                process_parser_config = d.spec.process_parser_config;

                // callback: throwError(0, callback()) -> immediate exit.
                if let Some(cb) = &d.spec.callback {
                    match cb {
                        CallbackKind::Help => return Err(ParseError::new(0, get_help_text(defs))),
                        CallbackKind::Version => {
                            return Err(ParseError::new(0, version_text(defs)));
                        }
                    }
                }
            } else {
                // Unknown option: replicate the JS quirk that crashes with
                // "Cannot read properties of undefined (reading 'full')" when the
                // unknown option has no value AND the next arg is also an option
                // (so flag=true). The crash happens later during missingValue
                // iteration because `options[optionName].full` is undefined for
                // the synthesized key.
                let real_option_name = option_name
                    .trim_start_matches('-')
                    .trim_start_matches("no-")
                    .to_string();
                let has_prev = options.contains_key(&real_option_name);
                let prev_not_true = match options.get(&real_option_name) {
                    Some(serde_json::Value::Bool(b)) => !*b,
                    Some(_) => true,
                    None => false,
                };
                let is_list_unknown = has_prev && prev_not_true;

                let next_is_option = i + 1 < args.len() && is_option(&args[i + 1]);
                let flag = !has_prev && value.is_none() && next_is_option;

                key = real_option_name.clone();
                is_flag = flag;
                is_list = is_list_unknown;

                if is_list_unknown {
                    let cur = options.get(&real_option_name).cloned();
                    if let Some(cur) = cur {
                        match cur {
                            serde_json::Value::Bool(true) => {
                                options.insert(
                                    real_option_name.clone(),
                                    serde_json::Value::Array(vec![]),
